import torch
class Model(torch.nn.Module):
 def forward(self,x):
  a,b=torch.unbind(input=x,dim=-1)
  return a+b*.25
def make():return Model()

import torch
class Model(torch.nn.Module):
 def forward(self,x):
  a,b=x.unbind()
  a.add_(b*.125)
  return a,x
def make():return Model()

import torch
class Model(torch.nn.Module):
 def forward(self,x):
  a,b=x.unbind()
  s=a.clone()
  x.mul_(.25)
  return s,a+b
def make():return Model()

import torch
class Model(torch.nn.Module):
 def forward(self,x):
  p=x.unbind()
  return torch.stack([p[-1],p[1],p[1]])
def make():return Model()

import torch
class Model(torch.nn.Module):
 def forward(self,x):
  return x.unbind()[0]
def make():return Model()

import torch
class Model(torch.nn.Module):
 def __init__(self):
  super().__init__()
  self.register_buffer('weight',torch.zeros(2,dtype=torch.float64))
 def forward(self,x):
  a,b=self.weight.unbind()
  return x*a+b
def make():return Model()

import torch
class Model(torch.nn.Module):
 def forward(self,x):
  d=torch.einsum("ii->i",x)
  d.add_(.125)
  return d,x
def make():return Model().eval()

import torch
class Model(torch.nn.Module):
 def __init__(self):
  super().__init__()
  self.register_buffer("w1",torch.zeros((4,4),dtype=torch.float64))
  self.register_buffer("w2",torch.zeros((2,4),dtype=torch.float64))
 def forward(self,x):
  x=torch.nn.functional.linear(x,self.w1)
  return torch.nn.functional.linear(x.square(),self.w2)
def make():return Model().eval()
